const clock = new THREE.Clock();
const propMaterials = [propMaterial_prop_636b3922, propMaterial_prop_476bbedd, propMaterial_prop_849a3f35, propMaterial_prop_f82f2918, propMaterial_prop_39693a6f, propMaterial_prop_5b362d74, propMaterial_prop_3fc36127];

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  if (skyUniforms && skyUniforms.uTime) skyUniforms.uTime.value = t;
  if (terrainMat && terrainMat.uniforms && terrainMat.uniforms.uTime) {
    terrainMat.uniforms.uTime.value = t;
  }
  for (const mat of propMaterials) {
    if (mat && mat.uniforms && mat.uniforms.uTime) {
      mat.uniforms.uTime.value = t;
    }
  }


  controls.update();
  renderer.render(scene, camera);
}

animate();

// Ресайз
window.addEventListener('resize', () => {
  const w = container.clientWidth;
  const h = container.clientHeight;
  if (!w || !h) return;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  
});

